 // File: rules.rs
 	#[verifier::external_body]
 proof fn always_unfold<T>(ex: Execution<T>, p: TempPred<T>)
     requires always(p).satisfied_by(ex),
     ensures forall |i: nat| p.satisfied_by(#[trigger] ex.suffix(i)),
 	{
 	// `always(p).satisfied_by(ex)` unfolds definitionally to
 	// `forall i: nat, p.satisfied_by(ex.suffix(i))`.
 	forall |i: nat| {
 		// Trigger the intended fact for Verus.
 		// The goal follows directly from the definition of `always`.
 		p.satisfied_by(#[trigger] ex.suffix(i))
 	};
 }

 proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
 	ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
 {
 	// Unfold the definition of `valid` (and thus the postcondition):
 	//   valid(r) = forall ex, r.satisfied_by(ex)
 	// where r is the implication.
 	forall |ex: Execution<T>|
 	    // Show the implication holds at this `ex`.
 	    always(p.and(q)).satisfied_by(ex) ==> {
 	        // Unfold `always` and build the `and` of the two `always` predicates.
 	        forall |i: nat|
 	            p.satisfied_by(ex.suffix(i)) && q.satisfied_by(ex.suffix(i))
 	    };
 }


 }

